CustomersService.profile.source:
async profile(id: string): Promise<CustomerProfile> {
  const customer = await this.customers.findOneBy({ id });
  if (!customer) throw new NotFoundException(`customer ${id}`);
  if (customer.blocked) throw new ForbiddenException(`customer ${id} is blocked`);
  return { id: customer.id, name: customer.name, email: customer.email, tier: customer.tier };
}

FraudService.assess.source:
async assess(input: RiskInput): Promise<Assessment> {
  const res = await firstValueFrom(this.http.post<{ score: number }>('https://risk.example.com/v1/score', {
    customerId: input.customerId, country: input.country, amount: input.total,
  }));
  const hold = needsReview(res.data.score, input.total, input.tier);
  await this.checks.insert({ customerId: input.customerId, score: res.data.score, hold });
  return { score: res.data.score, hold };
}

InventoryService.reserve.source:
async reserve(lines: OrderLine[]): Promise<void> {
  for (const line of lines) {
    const item = await this.stock.findOneBy({ productId: line.productId });
    if (!item || item.available < line.quantity) throw new ConflictException(`out of stock: ${line.productId}`);
    await this.stock.update({ productId: line.productId }, { available: item.available - line.quantity, reserved: item.reserved + line.quantity });
  }
}

InventoryService.release.source:
async release(lines: OrderLine[]): Promise<void> {
  for (const line of lines) {
    await this.stock.increment({ productId: line.productId }, 'available', line.quantity);
    await this.stock.decrement({ productId: line.productId }, 'reserved', line.quantity);
  }
}

