ShippingService.rates.source:
async rates(country: string, lines: OrderLine[]): Promise<number> {
  const parcels = Math.ceil(lines.reduce((n, l) => n + l.quantity, 0) / 5);
  return this.carrier.rate(country, parcels);
}

